var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    files: [],
    filesinfo: [],
  },
  methods: {
    getData() {
      const path = window.location.origin + "/dashboard/assets/data";
      axios
        .get(path)
        .then((response) => {
          this.filesinfo = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    updateData(index) {
      const path = window.location.origin + "/dashboard/assets";
      axios
        .post(path, {
          data: this.filesinfo[index],
        })
        .then((response) => {
          Vue.set(this.filesinfo[index], 'val', response.data);
        })
        .catch((error) => {
          console.log(error);
        });
    },
    async uploadData() {
      const formData = new FormData();
      for (let i = 0; i < this.files.length; i++) {
        const file = this.files[i];
        formData.append("files[" + i + "]", file);
      }
      const path = window.location.origin + "/dashboard/upload";
      const response = await axios
        .post(path, formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        })
        .then((response) => {
          this.files = [];
          this.filesinfo = response.data.data;
          this.$notify({
            group: 'notification',
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000
          })
        })
        .catch((error) => {
          return error.response;
        });
    },
    handleFilesUpload() {
      let uploadedFiles = this.$refs.files.files;
      for (var i = 0; i < uploadedFiles.length; i++) {
        this.files.push(uploadedFiles[i]);
      }
    },
    handleClickFiles() {
      this.$refs.files.click();
    },
    removePreFile(index) {
      this.files.splice(index, 1);
    },
    removeFile(index) {
      const path = window.location.origin + "/dashboard/assets/" + this.filesinfo[index].id;
      axios
        .delete(path)
        .then((response) => {
          this.$notify({
            group: 'notification',
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000
          })
        })
        .catch((error) => {
          console.log(error);
        });
      this.filesinfo.splice(index, 1);
    },
    copyFbAttr(text) {
      if (window.clipboardData && window.clipboardData.setData) {
        // IE specific code path to prevent textarea being shown while dialog is visible.
        return clipboardData.setData("", text);
      } else if (
        document.queryCommandSupported &&
        document.queryCommandSupported("copy")
      ) {
        var textarea = document.createElement("textarea");
        textarea.textContent = text;
        textarea.style.position = "fixed"; // Prevent scrolling to bottom of page in MS Edge.
        document.body.appendChild(textarea);
        textarea.select();
        try {
          return document.execCommand("copy"); // Security exception may be thrown by some browsers.
        } catch (error) {
          console.warn("Copy lỗi, tải lại trang và thử lại..", error);
          return false;
        } finally {
          document.body.removeChild(textarea);
        }
      }
    },
  },
  computed: {
    listfiles() {
      let PATTERN = ".csv";
      const newArr = this.filesinfo.map((v, index) => ({ ...v, aid: index }));
      return newArr.filter(function (file) {
        return file.key.indexOf(PATTERN) !== -1;
      });
    },
    listmedias() {
      let PATTERN = ".csv";
      const newArr = this.filesinfo.map((v, index) => ({ ...v, aid: index }));
      return newArr.filter(function (media) {
        return media.key.indexOf(PATTERN) === -1;
      });
    },
  },
  created() {
    this.getData();
  },
});
